const description = $input.first().json.work_order_description.toLowerCase();

const emergencyKeywords = ['flood', 'active leak', 'gas leak', 'no heat', 'no ac extreme temperature', 'electrical hazard', 'fire', 'lockout', 'sewage backup', 'broken exterior door', 'no water'];
const urgentKeywords = ['plumbing issue', 'appliance not working', 'hvac issue', 'water heater', 'toilet not working', 'refrigerator', 'oven', 'washer', 'dryer'];

let urgency = 'Normal';
let classificationMethod = 'keyword-based';
let manualReviewRequired = false;
let classificationFailed = false;

try {
  for (const keyword of emergencyKeywords) {
    if (description.includes(keyword)) {
      urgency = 'Emergency';
      break;
    }
  }

  if (urgency === 'Normal') {
    for (const keyword of urgentKeywords) {
      if (description.includes(keyword)) {
        urgency = 'Urgent';
        break;
      }
    }
  }
} catch (error) {
  urgency = 'Urgent';
  manualReviewRequired = true;
  classificationMethod = 'fallback-due-to-error';
  classificationFailed = true;
}

return [{
  json: {
    ...$input.first().json,
    urgency,
    classification_method: classificationMethod,
    classification_confidence: urgency === 'Normal' ? 0.7 : 0.9,
    manual_review_required: manualReviewRequired,
    classification_failed: classificationFailed
  }
}];

const item = $input.first().json;
const urgency = item.urgency;
const now = $now;

let slaDeadline;
let escalationStatus;

if (urgency === 'Emergency') {
  slaDeadline = now.plus({ minutes: 15 }).toISO();
  escalationStatus = 'Emergency SLA active';
} else if (urgency === 'Urgent') {
  let deadline = now;
  let hoursToAdd = 4;

  while (hoursToAdd > 0) {
    deadline = deadline.plus({ hours: 1 });
    const dayOfWeek = deadline.weekday;
    const hour = deadline.hour;

    if (dayOfWeek >= 1 && dayOfWeek <= 5 && hour >= 9 && hour < 17) {
      hoursToAdd--;
    }
  }

  slaDeadline = deadline.toISO();
  escalationStatus = 'Urgent SLA active';
} else {
  let deadline = now;
  let businessDaysToAdd = 1;

  while (businessDaysToAdd > 0) {
    deadline = deadline.plus({ days: 1 });
    const dayOfWeek = deadline.weekday;

    if (dayOfWeek >= 1 && dayOfWeek <= 5) {
      businessDaysToAdd--;
    }
  }

  deadline = deadline.set({ hour: 17, minute: 0, second: 0 });
  slaDeadline = deadline.toISO();
  escalationStatus = 'Normal SLA active';
}

return [{
  json: {
    ...item,
    sla_deadline: slaDeadline,
    escalation_status: escalationStatus
  }
}];
